// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/settings/SyncShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Settings → Sync → Repositories, ported from the app's ProjectsMenu
 * (src/panels/ProjectsMenu.tsx) with its PathField, AsyncButton, Switch and
 * DeviceIcon: the projects folder, the scanned devices, and one card per
 * Fieldnotes repository, `api` expanded to its line on each device and its
 * origin, baseline and env details.
 */
import { ChevronRight, FolderOpen, FolderSync, RefreshCw, type LucideIcon } from "lucide-react";
import type { ReactNode } from "react";
import { DeviceIcon } from "./DeviceIcon";
import { SettingsWindow } from "./SettingsWindow";

type Os = "mac" | "linux";

interface ScannedDevice {
  id: string;
  name: string;
  /** The SSH target ProjectsMenu's toRef gives a device; empty for this device. */
  host: string;
  os: Os;
  /** Where the projects root resolved on the device. */
  root: string;
  repos: number;
}

const ROOT = "~/fieldnotes";

const DEVICES: ScannedDevice[] = [
  { id: "this-mac", name: "This Device", host: "", os: "mac", root: "~/fieldnotes", repos: 3 },
  { id: "devbox", name: "Devbox", host: "devbox", os: "linux", root: "~/fieldnotes", repos: 2 },
];

type Tone = "ok" | "warn" | "bad" | "dim" | "acc";
type EnvState = "synced" | "differs" | "partial" | "single";

const ENV_LABEL: Record<EnvState, string> = {
  synced: "in sync",
  differs: "differs",
  partial: "partial",
  single: "only here",
};

const ENV_TITLE: Record<EnvState, string> = {
  synced: "same content on every device",
  differs: "content differs between devices",
  partial: "missing on Devbox",
  single: "the repo exists on one device only",
};

interface Env {
  name: string;
  state: EnvState;
}

/** The app's AsyncButton at rest (src/ui/AsyncButton.tsx). */
function AsyncButton({ className, icon: Icon, iconSize, title, children }: { className: string; icon: LucideIcon; iconSize: number; title: string; children: ReactNode }) {
  return (
    <button type="button" title={title} className={`${className} async-button`} aria-busy={false}>
      <span className="async-button-icon" style={{ width: iconSize, height: iconSize }} aria-hidden="true">
        <Icon size={iconSize} strokeWidth={2} />
      </span>
      {children}
    </button>
  );
}

/** The app's Switch, small (src/ui/Switch.tsx). */
function Switch({ on, title }: { on: boolean; title: string }) {
  return (
    <button type="button" className={`switch ${on ? "switch-on" : ""} switch-sm`} role="switch" aria-checked={on} title={title} aria-label={title}>
      <span className="switch-knob" />
    </button>
  );
}

function Badge({ tone, title, children }: { tone: Tone; title: string; children: string }) {
  return (
    <span className={`pj-badge pj-${tone}`} title={title}>
      {children}
    </span>
  );
}

function EnvChips({ envs }: { envs: Env[] }) {
  if (envs.length === 0) return null;
  return (
    <span className="pj-envs">
      {envs.map((env) => (
        <span key={env.name} className={`pj-env pj-env-${env.state}`} title={ENV_TITLE[env.state]}>
          {env.name}
          <span className="pj-env-state">{ENV_LABEL[env.state]}</span>
        </span>
      ))}
    </span>
  );
}

/** ProjectCard: the head with its env chips and switches, and, open, its device lines and details. */
function ProjectCard({ rel, envs, open = false, children }: { rel: string; envs: Env[]; open?: boolean; children?: ReactNode }) {
  return (
    <div className="pj-card ">
      <div className="pj-card-head" role="button" tabIndex={0} aria-expanded={open}>
        <ChevronRight size={13} className={`muted-icon pj-chev ${open ? "flip" : ""}`} />
        <span className="pj-rel" title={rel}>
          {rel}
        </span>
        <EnvChips envs={envs} />
        <span className="pj-card-switches">
          {envs.length > 0 ? (
            <span className="pj-switch-wrap" title="Env files sync for this project">
              <span className="pj-switch-label">env</span>
              <Switch on title="Sync env files for this project" />
            </span>
          ) : null}
          <span className="pj-switch-wrap" title="Included in sync">
            <span className="pj-switch-label">sync</span>
            <Switch on title="Include this project in sync" />
          </span>
        </span>
      </div>
      {open ? children : null}
    </div>
  );
}

/** DeviceLine for a checkout on the selected baseline. */
function DeviceLine({ device, head, children }: { device: ScannedDevice; head: string; children: ReactNode }) {
  return (
    <div className="pj-line">
      <span className="pj-line-device">
        <DeviceIcon os={device.os} />
        {device.name}
      </span>
      <span className="pj-line-body">
        <span className="pj-branch pj-acc" title="on selected baseline">
          development
        </span>
        <span className="pj-sha">{head}</span>
        <span className="pj-badges">{children}</span>
      </span>
    </div>
  );
}

function DetailLine({ device, children }: { device: ScannedDevice; children: string }) {
  return (
    <div className="pj-detail-line">
      <span className="pj-k">
        <DeviceIcon os={device.os} />
        {device.name}
      </span>
      <span className="pj-v">{children}</span>
    </div>
  );
}

function RepositoriesPage() {
  const [mac, devbox] = DEVICES;
  return (
    <div>
      <div className="settings-page pj">
        <div>
          <section className="settings-section">
            <label className="settings-field">
              <span>Projects folder</span>
              <fieldset className="pj-root-field">
                <button type="button" className="path-field  pj-root" title="Projects root: the same folder, relative to home, on every device">
                  <FolderOpen size={13} className="path-field-icon" />
                  <span className="path-field-value">{ROOT}</span>
                </button>
              </fieldset>
            </label>
            <div className="settings-actions">
              <AsyncButton className="btn btn-sm" icon={RefreshCw} iconSize={13} title="Rescan every device">
                Rescan
              </AsyncButton>
              <AsyncButton className="btn btn-sm btn-accent" icon={FolderSync} iconSize={13} title="Run sync with your saved preferences">
                Sync all
              </AsyncButton>
            </div>
          </section>

          <div className="pj-devices">
            {DEVICES.map((device) => (
              <div key={device.id} className="pj-device " title={`${device.host || "local"} · ${device.root}`}>
                <span className="dot dot-up" />
                <span className="pj-device-name">
                  <DeviceIcon os={device.os} />
                  {device.name}
                </span>
                <span className="pj-device-n">{`${device.repos} repos`}</span>
              </div>
            ))}
            <div className="ports-status-spacer" />
            <div className="pj-filter">
              <button className="pj-filter-btn on">
                all <b>3</b>
              </button>
              <button className="pj-filter-btn  ">
                attention <b>0</b>
              </button>
            </div>
          </div>

          <div className="pj-list">
            <ProjectCard rel="api" envs={[{ name: ".env", state: "differs" }]} open>
              <div className="pj-lines">
                <DeviceLine device={mac} head="4f2a91c">
                  <Badge tone="warn" title="tracked files with uncommitted changes">2 modified</Badge>
                  <Badge tone="acc" title="commits ahead of upstream">↑1 ahead</Badge>
                </DeviceLine>
                <DeviceLine device={devbox} head="9be03d7">
                  <Badge tone="bad" title="commits behind upstream">↓2 behind</Badge>
                </DeviceLine>
              </div>
              <div className="pj-details">
                <div className="pj-detail-line">
                  <span className="pj-k">origin</span>
                  <span className="pj-v">git@example.com:fieldnotes/api.git</span>
                </div>
                <div className="pj-detail-line">
                  <span className="pj-k">baseline</span>
                  <span className="pj-v">development</span>
                </div>
                <DetailLine device={mac}>last commit 2h ago · .env 3c9e1a7</DetailLine>
                <DetailLine device={devbox}>last commit 1d ago · .env 81d4b02</DetailLine>
              </div>
            </ProjectCard>
            <ProjectCard rel="docs" envs={[]} />
            <ProjectCard rel="web" envs={[{ name: ".env.local", state: "synced" }]} />
          </div>
          <p className="set-note pj-note">
            Sync clones missing repos onto remote development when available, otherwise remote main. It first preserves local
            edits in a durable stash and unmerged local commits in recovery refs, then aligns a clean checkout to that baseline
            without creating a merge commit. Each project, device, and behavior can opt out safely in its settings.
          </p>
        </div>
      </div>
    </div>
  );
}

export function SyncShot() {
  return (
    <SettingsWindow section="sync" page="repositories">
      <RepositoriesPage />
    </SettingsWindow>
  );
}
